void ArcAsyncWaiter::RequestActivityIcons(
    std::vector<ActivityNamePtr> activities, ScaleFactor scale_factor, std::vector<ActivityIconPtr>* out_icons, RequestActivityIconsStatus* out_status) {
  base::RunLoop loop;
  proxy_->RequestActivityIcons(std::move(activities),std::move(scale_factor),
      base::BindOnce(
          [](base::RunLoop* loop,
             std::vector<ActivityIconPtr>* out_icons
,
             RequestActivityIconsStatus* out_status
,
             std::vector<ActivityIconPtr> icons,
             RequestActivityIconsStatus status) {*out_icons = std::move(icons);*out_status = std::move(status);
            loop->Quit();
          },
          &loop,
          out_icons,
          out_status));
  loop.Run();
}



void ArcAsyncWaiter::RequestUrlHandlerList(
    const std::string& url, std::vector<IntentHandlerInfoPtr>* out_handlers, RequestUrlHandlerListStatus* out_status) {
  base::RunLoop loop;
  proxy_->RequestUrlHandlerList(std::move(url),
      base::BindOnce(
          [](base::RunLoop* loop,
             std::vector<IntentHandlerInfoPtr>* out_handlers
,
             RequestUrlHandlerListStatus* out_status
,
             std::vector<IntentHandlerInfoPtr> handlers,
             RequestUrlHandlerListStatus status) {*out_handlers = std::move(handlers);*out_status = std::move(status);
            loop->Quit();
          },
          &loop,
          out_handlers,
          out_status));
  loop.Run();
}



void ArcAsyncWaiter::RequestTextSelectionActions(
    const std::string& text, ScaleFactor scale_factor, RequestTextSelectionActionsStatus* out_status, std::vector<TextSelectionActionPtr>* out_actionos) {
  base::RunLoop loop;
  proxy_->RequestTextSelectionActions(std::move(text),std::move(scale_factor),
      base::BindOnce(
          [](base::RunLoop* loop,
             RequestTextSelectionActionsStatus* out_status
,
             std::vector<TextSelectionActionPtr>* out_actionos
,
             RequestTextSelectionActionsStatus status,
             std::vector<TextSelectionActionPtr> actionos) {*out_status = std::move(status);*out_actionos = std::move(actionos);
            loop->Quit();
          },
          &loop,
          out_status,
          out_actionos));
  loop.Run();
}



void ArcAsyncWaiter::IsInstallable(
    const std::string& package_name, IsInstallableResult* out_result) {
  base::RunLoop loop;
  proxy_->IsInstallable(std::move(package_name),
      base::BindOnce(
          [](base::RunLoop* loop,
             IsInstallableResult* out_result
,
             IsInstallableResult result) {*out_result = std::move(result);
            loop->Quit();
          },
          &loop,
          out_result));
  loop.Run();
}

IsInstallableResult ArcAsyncWaiter::IsInstallable(
    const std::string& package_name) {
  IsInstallableResult async_wait_result;
  IsInstallable(std::move(package_name),&async_wait_result);
  return async_wait_result;
}






